def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    if nanoseconds is None:
        return None
    try:
        total_seconds, nanos = divmod(nanoseconds, 10**9)
        seconds, minutes = divmod(total_seconds, 60)
        hours, minutes = divmod(minutes, 60)
        if tz is not None:
            return datetime.time(hours, minutes, seconds, nanos, tzinfo=tz)
        else:
            return datetime.time(hours, minutes, seconds, nanos)
    except (ValueError, TypeError, OverflowError):
        return None

def dehydrate_timedelta(value):
    """ Dehydrator for `timedelta` values.

    :param value:
    :type value: timedelta
    :return:
    """
    if value is None:
        return None
    try:
        return value.total_seconds()
    except AttributeError:
        return None

def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    if value is None:
        return None
    return value.strftime('%H:%M:%S')

