        """
        if protocol_version is not None and not isinstance(protocol_version, tuple):
            raise TypeError("protocol_version must be a tuple or None")

        # Get all available protocol handlers from the class
        # Assuming there's a class attribute or method that provides this
        # For now, we'll assume there's a class attribute _protocol_handlers
        # that maps version tuples to handler classes
        all_handlers = getattr(cls, '_protocol_handlers', {})

        if protocol_version is None:
