def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.

    """
    if maxsize is None or maxsize == 0:
        def decorator(func):
            @functools.wraps(func)
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
            wrapper.cache_info = lambda: _make_info(0, 0, 0, 0)
            wrapper.cache_clear = lambda: None
            return wrapper
        return decorator

    if not isinstance(maxsize, int):
        raise TypeError("Expected maxsize to be an integer or None")

    if maxsize < 0:
        raise ValueError("Expected maxsize to be greater than or equal to zero")

    if not isinstance(typed, bool):
        raise TypeError("Expected typed to be a boolean")

    def decorator(func):
        cache = OrderedDict()
        cache_hits = 0
        cache_misses = 0

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            nonlocal cache_hits, cache_misses
            key = _make_key(args, kwargs, typed)
            try:
                result = cache[key]
                cache.move_to_end(key)
                cache_hits += 1
                return result
            except KeyError:
                cache_misses += 1
                result = func(*args, **kwargs)
                cache[key] = result
                if len(cache) > maxsize:
                    cache.popitem(last=False)
                return result

        def cache_info():
            return _make_info(cache_hits, cache_misses, maxsize, len(cache))

        def cache_clear():
            nonlocal cache_hits, cache_misses
            cache.clear()
            cache_hits = 0
            cache_misses = 0

        wrapper.cache_info = cache_info
        wrapper.cache_clear = cache_clear
        return wrapper

    return decorator
