def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    self._context = {}
    if self._initial_value is not None:
        self._bins = [self._initial_value] * self._n_bins
    else:
        self._bins = self._make_bins()

def _update_context(self, context):
    """Update *context* with the properties of this graph.

    *context.error* is appended with indices of errors.
    Example subcontext for a graph with fields "E,t,error_E_low":
    {"error": {"x_low": {"index": 2}}}.
    Note that error names are called "x", "y" and "z"
    (this corresponds to first three coordinates,
    if they are present), which allows to simplify plotting.
    Existing values are not removed
    from *context.value* and its subcontexts.

    Called on "destruction" of the graph (for example,
    in :class:`.ToCSV`). By destruction we mean conversion
    to another structure (like text) in the flow.
    The graph object is not really destroyed in this process.
    """
    if not hasattr(self, 'fields') or not hasattr(self, 'data'):
        return

    # Map field names to coordinate names (x, y, z)
    # Assuming the first three fields are coordinates if they exist
    coord_map = {}
    for i, field in enumerate(self.fields):
        if i < 3:
            coord_map[field] = ['x', 'y', 'z'][i]
        else:
            coord_map[field] = field

    # Initialize error context if not present
    if 'error' not in context:
        context['error'] = {}

    # Initialize value context if not present
    if 'value' not in context:
        context['value'] = {}

    # Process each data point
    for idx, point in enumerate(self.data):
        # Update value context
        for field in self.fields:
            if field in point:
                coord_name = coord_map.get(field, field)
                if coord_name not in context['value']:
                    context['value'][coord_name] = {}
                context['value'][coord_name][idx] = point[field]

        # Update error context
        for field in self.fields:
            if field.startswith('error_'):
                # Extract the base field name
                base_field = field[6:]  # Remove 'error_' prefix
                if base_field in coord_map:
                    coord_name = coord_map[base_field]
                    # Determine if it's low or high
                    if field.endswith('_low'):
                        error_type = 'low'
                    elif field.endswith('_high'):
                        error_type = 'high'
                    else:
                        error_type = 'error'

                    error_key = f"{coord_name}_{error_type}"
                    if error_key not in context['error']:
                        context['error'][error_key] = {}
                    context['error'][error_key][idx] = point[field]

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    if isinstance(seq, FillRequest):
        return True
    if isinstance(seq, Source):
        return False
    if isinstance(seq, (list, tuple, set)):
        return any(isinstance(item, FillRequest) for item in seq)
    return False

