def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if inventory is None:
        raise ValueError("inventory cannot be None")
    if version is None:
        raise ValueError("version cannot be None")

    # Assuming inventory is a dictionary or object that provides access to
    # logical paths and their associated content files for a given version.
    # The exact structure of inventory is not specified, so we make reasonable
    # assumptions based on common patterns.

    # If inventory is a dictionary mapping versions to logical path maps
    if isinstance(inventory, dict):
        if version not in inventory:
            raise KeyError(f"Version {version} not found in inventory")
        version_data = inventory[version]

        # If version_data is a dictionary mapping logical paths to content files
        if isinstance(version_data, dict):
            logical_path_map = {}
            for logical_path, content_files in version_data.items():
                # Ensure content_files is a set
                if isinstance(content_files, (list, tuple, set)):
                    logical_path_map[logical_path] = set(content_files)
                else:
                    logical_path_map[logical_path] = {content_files}
            return logical_path_map
        else:
            raise TypeError(f"Expected version data to be a dictionary, got {type(version_data)}")
    else:
        # If inventory is an object with a method to get logical path map
        if hasattr(inventory, 'get_logical_path_map'):
            return inventory.get_logical_path_map(version)
        elif hasattr(inventory, 'logical_path_map'):
            return inventory.logical_path_map.get(version, {})
        else:
            raise AttributeError("inventory does not have the expected structure or methods")
