def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import os

    # Combine commands and args into a single list
    cmd_list = list(commands) + list(args)

    # Prepare environment
    if env is None:
        env = os.environ.copy()
    else:
        env = os.environ.copy()
        env.update(env)

    # Prepare subprocess kwargs
    kwargs = {
