        'stdout': subprocess.PIPE,
        'stderr': subprocess.PIPE if not hide_stderr else subprocess.DEVNULL,
    }

    if verbose:
        print("Running command: {}".format(' '.join(cmd_list)))

    try:
        process = subprocess.Popen(cmd_list, **kwargs)
        stdout, stderr = process.communicate()
        if verbose:
            if stdout:
                print("STDOUT: {}".format(stdout.decode('utf-8', errors='replace')))
            if stderr and not hide_stderr:
                print("STDERR: {}".format(stderr.decode('utf-8', errors='replace')))
