def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if not isinstance(params, dict):
        raise TypeError("params must be a dictionary")
    if not isinstance(bug_ids, (list, tuple)):
        raise TypeError("bug_ids must be a list or tuple")

    # Ensure all bug_ids are valid integers
    for bug_id in bug_ids:
        if not isinstance(bug_id, int):
            raise TypeError("All bug_ids must be integers")

    # Create a copy of the params to avoid modifying the original
    amended_params = params.copy()

    # Add or update the bug_ids in the params
    if 'id' in amended_params:
        if isinstance(amended_params['id'], (list, tuple)):
            # If id is already a list, extend it with new bug_ids
            existing_ids = set(amended_params['id'])
            new_ids = [bug_id for bug_id in bug_ids if bug_id not in existing_ids]
            amended_params['id'] = list(existing_ids) + new_ids
        else:
            # If id is a single value, convert to list and add new bug_ids
            existing_id = amended_params['id']
            new_ids = [bug_id for bug_id in bug_ids if bug_id != existing_id]
            amended_params['id'] = [existing_id] + new_ids
    else:
        # If no id exists, set it to the list of bug_ids
        amended_params['id'] = list(bug_ids)

    return amended_params
