def deep_merge_nodes(nodes):
    if not nodes:
        return []

    merged = {}
    order = []

    for key, value in nodes:
        key_str = key.value if hasattr(key, 'value') else str(key)

        if key_str not in merged:
            merged[key_str] = value
            order.append(key_str)
        else:
            existing_value = merged[key_str]

            if isinstance(existing_value, MappingNode) and isinstance(value, MappingNode):
                merged[key_str] = MappingNode(
                    tag=existing_value.tag,
                    value=deep_merge_nodes(existing_value.value + value.value)
                )
            else:
                merged[key_str] = value

    return [(key, merged[key.value if hasattr(key, 'value') else str(key)]) for key in [k for k in nodes if k.value if hasattr(k, 'value') else str(k) in order]]

