def isoparse(self, dt_str):
    if not isinstance(dt_str, (str, bytes)):
        raise TypeError("isoparse() argument must be a string or bytes, not %s" % type(dt_str).__name__)

    if isinstance(dt_str, bytes):
        dt_str = dt_str.decode('ascii')

    # Split the string into date and time parts
    # The separator is 'T' or 't'
    if 'T' in dt_str:
        date_str, time_str = dt_str.split('T', 1)
    elif 't' in dt_str:
        date_str, time_str = dt_str.split('t', 1)
    else:
        date_str = dt_str
        time_str = None

    # Parse the date part
    date_obj = self._parse_date(date_str)

    # Parse the time part if it exists
    if time_str is not None:
        time_obj = self._parse_time(time_str)
    else:
        time_obj = None

    # Combine date and time
    if time_obj is not None:
        dt = datetime.datetime.combine(date_obj, time_obj)
    else:
        dt = datetime.datetime(date_obj.year, date_obj.month, date_obj.day)

    return dt

