def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        data = json.loads(document)
        if "links" in data:
            return data
        raise ValueError("Invalid JSON webfinger document")
    except (json.JSONDecodeError, ValueError):
        pass

    try:
        root = ElementTree.fromstring(document)
        if root.tag != "{http://docs.oasis-open.org/ns/xri/xrd-1.0}XRD":
            raise ValueError("Invalid XRD webfinger document")
        links = []
        for link in root.findall("{http://docs.oasis-open.org/ns/xri/xrd-1.0}Link"):
            link_dict = {
                "rel": link.get("rel"),
                "type": link.get("type"),
                "template": link.get("template"),
                "href": link.get("href"),
            }
            links.append(link_dict)
        return {"links": links}
    except (ElementTree.ParseError, ValueError, AttributeError):
        return {}

