def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
       """
    if not isinstance(values_dict, dict):
        return

    # Get the parser for the given command name
    parser = self._parsers.get(parser_name)
    if parser is None:
        return

    # Iterate over the arguments in the parser
    for action in parser._actions:
        # Skip actions that don't have a dest (like help)
        if not action.dest:
            continue

        # Get the argument name (dest)
        arg_name = action.dest

        # Check if the argument is in the values_dict
        if arg_name in values_dict:
            value = values_dict[arg_name]

            # If the value is None, skip conversion
            if value is None:
                continue

            # If the action has a type, use it to convert the value
            if action.type is not None:
                try:
                    values_dict[arg_name] = action.type(value)
                except (ValueError, TypeError):
                    # If conversion fails, leave the value as is
                    pass
            # If the action is a store_true or store_false, convert to bool
            elif action.const is not None and action.const in (True, False):
                try:
                    values_dict[arg_name] = bool(value)
                except (ValueError, TypeError):
                    pass

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    spec_file = os.path.join(plugin_dir, 'plugin.json')
    if not os.path.exists(spec_file):
        return {}

    try:
        with open(spec_file, 'r') as f:
            spec = json.load(f)
    except (json.JSONDecodeError, IOError):
        return {}

    def flatten(d, parent_key='', sep='.'):
        items = []
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.extend(flatten(v, new_key, sep=sep).items())
            else:
                items.append((new_key, v))
        return dict(items)

    return flatten(spec)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    if 'CONFIG_PATH' not in os.environ:
        os.environ['CONFIG_PATH'] = self.config_path

